//! Typed errors carrying a Spark error class and SQLSTATE (ADR 0008, 0029).
//!
//! The registry is generated by `build.rs` from `spark-error-conditions.json`
//! (Spark 4.2.0's `error-conditions.json`, vendored verbatim) plus
//! `krishiv-error-classes.json`. Spark classes copy Spark's name, SQLSTATE and
//! message template; Krishiv-only classes are prefixed `KRISHIV_`. The whole
//! Spark catalog is data; the classes the engine actually raises are the ones
//! referenced from engine code (see `cargo xtask registry-coverage`).
//!
//! Each class has a generated parameter struct, so a missing or extra
//! message parameter is a compile error:
//!
//! ```
//! use krishiv_common::error::{DivideByZero, ErrorClass, KrishivError};
//!
//! let e = KrishivError::from(DivideByZero { config: "\"spark.sql.ansi.enabled\"".into() });
//! assert_eq!(e.error_class(), ErrorClass::DivideByZero);
//! assert_eq!(e.sql_state(), Some("22012"));
//! ```
//!
//! ```compile_fail
//! // Missing parameter `config`.
//! let _ = krishiv_common::error::DivideByZero {};
//! ```
//!
//! ```compile_fail
//! // Extra parameter `hint`.
//! let _ = krishiv_common::error::DivideByZero { config: String::new(), hint: String::new() };
//! ```

#[cfg_attr(
    not(test),
    expect(
        dead_code,
        reason = "`placeholders` is used by build.rs and tests only"
    )
)]
mod template;

include!(concat!(env!("OUT_DIR"), "/error_classes.rs"));

/// An error with a Spark error class, SQLSTATE and message parameters.
///
/// `Display` matches Spark 4's `getMessage` without query context:
/// `[ERROR_CLASS] message SQLSTATE: xxxxx` (no suffix for the Spark classes
/// that have no SQLSTATE). Like Spark, `_LEGACY_ERROR_TEMP_*` classes omit
/// the `[ERROR_CLASS]` prefix.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
#[error("{}{message}{}", class_prefix(*class), sql_state_suffix(*class))]
pub struct KrishivError {
    class: ErrorClass,
    parameters: Vec<(&'static str, String)>,
    message: String,
}

fn class_prefix(class: ErrorClass) -> String {
    if class.name().starts_with("_LEGACY_ERROR_TEMP_") {
        String::new()
    } else {
        format!("[{}] ", class.name())
    }
}

fn sql_state_suffix(class: ErrorClass) -> String {
    class
        .sql_state()
        .map_or_else(String::new, |s| format!(" SQLSTATE: {s}"))
}

impl KrishivError {
    /// Builds an error; callers outside this module go through the generated
    /// parameter structs, which guarantee `parameters` match the template.
    fn from_parts(class: ErrorClass, parameters: Vec<(&'static str, String)>) -> Self {
        let message = template::render(class.message_template(), &parameters);
        Self {
            class,
            parameters,
            message,
        }
    }

    /// The error class.
    pub fn error_class(&self) -> ErrorClass {
        self.class
    }

    /// The SQLSTATE of the error class, if Spark defines one.
    pub fn sql_state(&self) -> Option<&'static str> {
        self.class.sql_state()
    }

    /// The rendered message, without the `[CLASS]` prefix or SQLSTATE suffix.
    pub fn message(&self) -> &str {
        &self.message
    }

    /// Message parameters as `(spark_name, value)`, in template order.
    pub fn message_parameters(&self) -> &[(&'static str, String)] {
        &self.parameters
    }
}

/// Renders the error-class reference as Markdown (`cargo xtask docs-errors`).
pub fn docs_markdown() -> String {
    let mut out = String::from(
        "# Krishiv error classes\n\n\
         <!-- @generated by `cargo xtask docs-errors` from the error-class JSON files; do not edit. -->\n\n\
         | Error class | SQLSTATE | Message template |\n\
         |---|---|---|\n",
    );
    for c in ErrorClass::ALL {
        let template = c
            .message_template()
            .replace('&', "&amp;")
            .replace('<', "&lt;")
            .replace('>', "&gt;")
            .replace('|', "\\|")
            .replace('\n', "<br>");
        out.push_str(&format!(
            "| `{}` | `{}` | {} |\n",
            c.name(),
            c.sql_state().unwrap_or("-"),
            template.trim_end()
        ));
    }
    out
}

